options.helpers:
const frames = (context.panelData || context.panel.data).series || [];
const frameWith = (has, without) => frames.find((f) =>
  has.every((n) => f.fields.some((x) => x.name === n)) &&
  (without || []).every((n) => !f.fields.some((x) => x.name === n)));
const last = (frame, name) => {
  if (!frame) { return undefined; }
  const field = frame.fields.find((x) => x.name === name);
  if (!field || !field.values.length) { return undefined; }
  for (let i = field.values.length - 1; i >= 0; i -= 1) {
    if (field.values[i] !== null && field.values[i] !== undefined) { return field.values[i]; }
  }
  return undefined;
};

const node = frameWith(['status'], ['modelo']);
const tele = frameWith(['temperature_c']);
const act = frameWith(['heater']);
const sys = frameWith(['state', 'locked']);
const vis = frameWith(['status', 'clases']);
const ml = frameWith(['status', 'umbral'], ['puntaje']);
const visOut = frameWith(['clase', 'confianza']);
const mlOut = frameWith(['puntaje', 'umbral']);
// Un retenido de estado puede perderse si el panel se suscribe tarde; el flujo
// de datos reciente también prueba que el servicio está vivo.
const fresh = (frame) => {
  const time = frame && frame.fields.find((x) => x.type === 'time');
  return !!time && time.values.length > 0 && Date.now() - time.values[time.values.length - 1] < 15000;
};
const chip = (label, value, tone, detail) => ({ label, value, tone, detail });
const bool = (label, v, onText, offText, toneOn, detailOn, detailOff) => v === undefined
  ? chip(label, 'Sin datos', 'idle', 'esperando mensaje')
  : chip(label, v ? onText : offText, v ? toneOn : 'idle', v ? detailOn : detailOff);
const service = (label, v, alive, detail) => {
  if (alive || v === 'online') { return chip(label, 'En línea', 'ok', detail); }
  if (v === 'offline') { return chip(label, 'Caído', 'alarm', 'Last Will recibido'); }
  return chip(label, 'Sin señal', 'idle', 'sin mensajes recientes');
};
const locked = last(sys, 'locked');
const chips = [
  service('Nodo', last(node, 'status'), fresh(tele), 'telemetría en vivo'),
  locked === undefined ? chip('Sistema', 'Sin datos', 'idle', 'sistema/estado')
    : chip('Sistema', locked ? 'Bloqueado' : 'Normal', locked ? 'alarm' : 'ok', locked ? 'pasa una tarjeta RFID' : 'sin objetos extraños'),
  bool('Puerta', last(tele, 'door_open'), 'Abierta', 'Cerrada', 'heat', 'final de carrera', 'final de carrera'),
  bool('Calefactor', last(act, 'heater'), 'Encendido', 'Apagado', 'heat', 'foco 40 W', 'en espera'),
  bool('Ventilador', last(act, 'fan'), 'Encendido', 'Apagado', 'cyan', 'enfriando', 'en espera'),
  bool('Buzzer', last(act, 'buzzer'), 'Sonando', 'Silencio', 'alarm', 'alerta activa', 'sin alertas'),
  service('Visión', last(vis, 'status'), fresh(visOut), 'MobileNetV2 · ONNX'),
  service('Detector ML', last(ml, 'status'), fresh(mlOut), 'Local Outlier Factor'),
];
context.handlebars.registerHelper('seChips', () => chips);

