options.content:
{{#with (seVision)}}
{{#if ready}}
<div class="se-vision se-{{tone}}">
  <div class="se-top">
    <div><span class="se-label">Última foto</span><strong>{{clase}}</strong></div>
    <div class="se-conf"><span class="se-mono">{{confianza}}<small>%</small></span><span class="se-label">confianza</span></div>
  </div>
  <div class="se-bars">
    {{#each bars}}
    <div class="se-bar se-{{tone}}"><span class="se-label">{{name}}</span><div class="se-track"><i style="width: {{value}}%"></i></div><span class="se-mono">{{value}}%</span></div>
    {{/each}}
  </div>
  <div class="se-window">
    <span class="se-label">Ventana de 5 fotos · media de objeto {{media}}%</span>
    <div class="se-dots">{{#each votes}}<i class="se-dot se-{{this}}"></i>{{/each}}</div>
  </div>
  {{#if detectado}}<div class="se-banner">Objeto confirmado · se envía el bloqueo al nodo</div>{{/if}}
  <div class="se-foot se-mono">inferencia {{ms}} ms · regla: objeto medio ≥ 65 % en 5 fotos</div>
</div>
{{else}}
<div class="se-empty"><span class="se-label">Visión</span><p>Esperando la primera foto de la bandeja…</p></div>
{{/if}}
{{/with}}

