    if (field.values[i] !== null && field.values[i] !== undefined) { return field.values[i]; }
  }
  return undefined;
};

const vis = frameWith(['clase', 'probabilidades']);
const names = { huevo: 'Huevo', objeto: 'Objeto extraño', vacio: 'Bandeja vacía' };
const probs = last(vis, 'probabilidades') || {};
const pct = (v) => Math.round((v || 0) * 100);
const clase = last(vis, 'clase');
const votesField = vis && vis.fields.find((x) => x.name === 'prob_objeto_media');
const objField = vis && vis.fields.find((x) => x.name === 'probabilidades');
const recent = objField ? objField.values.slice(-5).map((p) => (p && p.objeto > 0.5)) : [];
while (recent.length < 5) { recent.unshift(null); }
const view = {
  ready: clase !== undefined,
  clase: names[clase] || clase,
  tone: clase === 'objeto' ? 'alarm' : clase === 'huevo' ? 'ok' : 'cyan',
  confianza: pct(last(vis, 'confianza')),
  media: pct(last(vis, 'prob_objeto_media')),
  detectado: last(vis, 'objeto_detectado') === true,
  ms: last(vis, 'inferencia_ms'),
  bars: [
    { name: 'Huevo', value: pct(probs.huevo), tone: 'ok' },
    { name: 'Objeto', value: pct(probs.objeto), tone: 'alarm' },
    { name: 'Vacía', value: pct(probs.vacio), tone: 'cyan' },
  ],
  votes: recent.map((v) => (v === null ? 'empty' : v ? 'hit' : 'miss')),
};
context.handlebars.registerHelper('seVision', () => view);

