options.helpers:
const frames = (context.panelData || context.panel.data).series || [];
const frameWith = (has, without) => frames.find((f) =>
  has.every((n) => f.fields.some((x) => x.name === n)) &&
  (without || []).every((n) => !f.fields.some((x) => x.name === n)));
const last = (frame, name) => {
  if (!frame) { return undefined; }
  const field = frame.fields.find((x) => x.name === name);
  if (!field || !field.values.length) { return undefined; }
  for (let i = field.values.length - 1; i >= 0; i -= 1) {
    if (field.values[i] !== null && field.values[i] !== undefined) { return field.values[i]; }
  }
  return undefined;
};

const sys = frameWith(['state', 'locked']);
const reasons = { object_detected: 'La cámara detectó un objeto extraño en la bandeja' };
const locked = last(sys, 'locked');
const field = sys && sys.fields.find((x) => x.name === 'locked');
let changes = 0;
if (field) { for (let i = 1; i < field.values.length; i += 1) { if (field.values[i] && !field.values[i - 1]) { changes += 1; } } }
const when = last(sys, 'recorded_at');
const view = {
  ready: locked !== undefined,
  locked: locked === true,
  reason: reasons[last(sys, 'reason')] || 'Sin restricciones: el nodo opera de forma automática',
  since: when ? new Date(when).toLocaleTimeString('es-GT', { hour: '2-digit', minute: '2-digit', second: '2-digit' }) : '',
  changes,
};
context.handlebars.registerHelper('seLock', () => view);
